89: async function goi<T>(method: "GET" | "POST", url: string, body?: unknown): Promise<KetQua<T>> {
90:   try {
91:     const r = await fetch(url, {
92:       method,
93:       cache: "no-store",
94:       headers: body === undefined ? undefined : { "Content-Type": "application/json" },
95:       body: body === undefined ? undefined : JSON.stringify(body),
96:     });
97:     const d = (await r.json().catch(() => null)) as
98:       | (T & { message?: string; detail?: unknown; error?: string })
99:       | null;
100:     if (r.ok && d) return { ok: true, data: d };
101:     const ct = typeof d?.detail === "string" ? d.detail : null;
102:     const thongDiep = d?.message ?? ct ?? d?.error ?? "Máy chủ từ chối.";
103:     const loiKyThuat = /mã lỗi\s*[a-f\d-]+|lỗi chưa lường trước/i.test(thongDiep);
104:     return {
105:       ok: false,
106:       loi: loiKyThuat ? null : thongDiep,
107:     };
108:   } catch {
109:     return { ok: false, loi: "Mất kết nối — CHƯA lưu." };
110:   }

